INSERT INTO [dbo].[GALLERY_ITEM] ([Gallery_Item_Guid], [Icon_File_Name_Small], [Icon_File_Name_Large], [Configuration_Setup], [Description], [Configuration_Setup_Client], [Title], [Is_Visible], [CreationDate]) VALUES ('33ee6e8e-f317-45c2-9a09-cff50226ca8d', N'CRR.png', N'CRR.png', N'{"Model":{"ModelName":"CRR"}}', N'The CRR is a no-cost, voluntary, non-technical assessment to evaluate an organization''s operational resilience and cybersecurity practices. The CRR may be conducted as a self-assessment or as a facilitated assessment. The CRR assesses enterprise programs and practices across a range of ten domains including risk management, incident management, service continuity, and others. The assessment is designed to measure existing organizational resilience as well as provide a gap analysis for improvement based on recognized best practices.', NULL, N'CISA Cyber Resilience Review (CRR)', 0, '2022-09-20 15:26:46.847')
